const $=selector=>document.querySelector(selector);
const money=new Intl.NumberFormat("th-TH",{style:"currency",currency:"THB",maximumFractionDigits:2});
const state={user:null,products:[],orders:[],users:[],staff:[],ownerRequests:[],agents:[],commissions:[],promotions:[],walletRequests:[],closings:[],closingPreview:null,posCart:[],reports:null,lastChatId:0,chatTimer:null,sound:{enabled:true,volume:1,data:"",name:"เสียงมาตรฐาน JIGᶻ"},knownNewOrders:null,orderMonitorTimer:null,audioContext:null};
addEventListener("DOMContentLoaded",()=>document.querySelector('#orderStatus option[value="NEW"]')?.insertAdjacentHTML("afterend",'<option value="ACCEPTED">รับงานแล้ว</option>'));
addEventListener("DOMContentLoaded",()=>api("/api/settings/public").then(({settings})=>{document.body.dataset.theme=settings.theme||"space"}).catch(()=>{}));
addEventListener("DOMContentLoaded",()=>$("#setTheme").addEventListener("change",event=>{document.body.dataset.theme=event.target.value}));
const labels={NEW:"ออเดอร์ใหม่ / COD",ACCEPTED:"รับงานแล้ว",PENDING_PAYMENT:"รอชำระเงิน",PAID:"ชำระแล้ว",PACKING:"กำลังแพ็ก",PACKED:"แพ็กแล้ว",SHIPPED:"จัดส่งแล้ว",COMPLETED:"สำเร็จ",CANCELLED:"ยกเลิก"};

function esc(value){return String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]))}
function date(value){if(!value)return"—";return new Date(String(value).replace(" ","T")+(/Z|[+-]\d\d/.test(value)?"":"Z")).toLocaleString("th-TH")}
function status(value){return`<b class="status-${esc(value)}">${esc(labels[value]||value)}</b>`}
function toast(message){const element=$("#toast");element.textContent=message;element.classList.add("show");setTimeout(()=>element.classList.remove("show"),2200)}
function modal(title,content){$("#modalTitle").textContent=title;$("#modalBody").innerHTML=content;$("#modal").classList.remove("hidden")}
function closeModal(){$("#modal").classList.add("hidden")}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{"content-type":"application/json",...(options.headers||{})}});let body={};try{body=await response.json()}catch{}if(!response.ok)throw new Error(body.error||"request_failed");return body}
function errorText(error){const value=error?.message||"request_failed";if(value.startsWith("insufficient_stock"))return`สต็อกไม่พอ: ${value.split(":")[1]||"สินค้า"}`;return({invalid_customer:"กรอกข้อมูลลูกค้าให้ครบ",empty_cart:"ยังไม่มีสินค้า",invalid_transition:"สถานะนี้ยังทำรายการดังกล่าวไม่ได้",tracking_required:"กรอกบริษัทขนส่งและเลขพัสดุ",no_subscription:"ยังไม่ได้เปิดแจ้งเตือน",service_unavailable:"ระบบฐานข้อมูลไม่พร้อม",owner_required:"รายการนี้ทำได้เฉพาะ OWNER",primary_owner_required:"รายการนี้ต้องยืนยันโดย OWNER หลัก",secondary_owner_limit:"แต่งตั้ง OWNER รองครบสูงสุด 4 คนแล้ว",primary_owner_protected:"OWNER หลักไม่สามารถถูกลบได้",owner_protected:"ไม่สามารถเปลี่ยนสิทธิ์ OWNER ด้วยวิธีนี้",owner_request_not_found:"ไม่พบคำขอลบ OWNER",owner_request_processed:"คำขอนี้ถูกดำเนินการแล้ว",owner_request_target_changed:"สิทธิ์ของผู้ใช้เปลี่ยนไป กรุณาตรวจสอบใหม่",invalid_owner_decision:"ผลการตรวจคำขอไม่ถูกต้อง",user_not_found:"ไม่พบผู้ใช้",user_balance_not_zero:"ลบไม่ได้: ผู้ใช้ยังมีเครดิตคงเหลือ กรุณาจัดการยอดให้เป็นศูนย์ก่อน",user_wallet_pending:"ลบไม่ได้: ผู้ใช้ยังมีคำขอฝากหรือถอนที่รอตรวจ",linked_user_not_found:"ไม่พบ User ID ที่ต้องการเชื่อม",user_already_agent:"User ID นี้เชื่อมกับตัวแทนรายอื่นแล้ว",wallet_request_not_found:"ไม่พบคำขอฝาก–ถอน",wallet_request_processed:"คำขอนี้ถูกดำเนินการแล้ว",invalid_wallet_status:"สถานะคำขอไม่ถูกต้อง",product_not_found:"ไม่พบสินค้า",invalid_price_tier_form:"กรุณากรอกจำนวนและราคาให้ครบ ห้ามใช้จำนวนซ้ำ",agent_not_found:"ไม่พบตัวแทน",commission_not_found:"ไม่พบรายการค่าคอม",commission_paid_locked:"ค่าคอมนี้จ่ายเข้ากระเป๋าแล้ว จึงแก้หรือลบไม่ได้",promotion_not_found:"ไม่พบโปรโมชั่น",invalid_commission:"ข้อมูลค่าคอมไม่ถูกต้อง หรือกรุณาใช้ปุ่มจ่ายค่าคอม",invalid_audio:"รองรับไฟล์เสียง MP3, WAV, OGG และ M4A เท่านั้น",audio_too_large:"ไฟล์เสียงต้องมีขนาดไม่เกิน 900 KB",cod_payment_required:"ต้องยืนยันว่าได้รับยอด COD ก่อนปิดออเดอร์",invalid_cod_state:"ยืนยันยอด COD ได้หลังจัดส่งออเดอร์ COD เท่านั้น",invalid_closing_period:"กรุณาเลือกวันหรือเดือนที่ต้องการปิดยอด",invalid_actual_cash:"จำนวนเงินสดนับจริงไม่ถูกต้อง",closing_exists:"รอบนี้ถูกปิดยอดแล้ว ไม่สามารถปิดซ้ำได้",invalid_image:"รองรับไฟล์ JPG, PNG และ WebP เท่านั้น",too_many_images:"ใส่รูปสินค้าได้สูงสุด 5 รูป",image_too_large:"รูปมีขนาดใหญ่เกินไป กรุณาเลือกรูปใหม่",payload_too_large:"ข้อมูลไฟล์รวมมีขนาดใหญ่เกินไป"})[value]||value}

function showView(id){document.querySelectorAll(".page").forEach(page=>page.classList.toggle("active",page.id===id));document.querySelectorAll("#nav [data-view]").forEach(button=>button.classList.toggle("active",button.dataset.view===id));$("#app").classList.remove("menu-open");loadView(id);scrollTo(0,0)}
async function loadView(id){if(id==="dashboard")await loadDashboard();if(["orders","payments","shipping"].includes(id))await loadOrders();if(["products","pos"].includes(id))await loadProducts();if(id==="customers")await loadUsers();if(id==="staff")await loadStaff();if(id==="agents")await loadAgents();if(id==="promotions")await loadPromotions();if(id==="wallet")await loadWalletRequests();if(id==="closings")await loadClosings();if(["finance","reports"].includes(id))await loadReports();if(id==="settings")await loadSettings();if(id==="chat")await loadChat()}

async function loadDashboard(){try{const [{summary},orders]=await Promise.all([api("/api/admin/summary"),api("/api/admin/orders")]);$("#mOrders").textContent=summary.orders;$("#mTodayOrders").textContent=`วันนี้ ${summary.todayOrders} ออเดอร์`;$("#mPending").textContent=summary.pending;$("#mPacking").textContent=summary.packing;$("#mShipping").textContent=summary.shipping;$("#mLow").textContent=summary.lowStock;$("#mSales").textContent=money.format(summary.todaySales);$("#mOnline").textContent=summary.onlineUsers;$("#mAgents").textContent=summary.activeAgents;$("#mCommission").textContent=money.format(summary.pendingCommission);$("#orderPill").textContent=summary.orders;$("#paymentPill").textContent=summary.pending;$("#shippingPill").textContent=summary.shipping;state.orders=orders.orders;$("#latestOrders").innerHTML=state.orders.slice(0,7).map(order=>`<div class="order-mini"><div><b>${esc(order.id)}</b><small>${esc(order.customer_name)} · ${status(order.status)}</small></div><b>${money.format(order.total)}</b><button class="button small" data-order-detail="${esc(order.id)}">เปิด</button></div>`).join("")}catch(error){toast(errorText(error))}}

async function loadOrders(){try{const query=new URLSearchParams(),search=$("#orderSearch")?.value.trim(),selected=$("#orderStatus")?.value;if(search)query.set("q",search);if(selected)query.set("status",selected);state.orders=(await api(`/api/admin/orders?${query}`)).orders;renderOrders();renderPayments();renderShipping()}catch(error){toast(errorText(error))}}
function actions(order){let main={NEW:["ACCEPTED","รับงาน"],ACCEPTED:["PACKING","เริ่มแพ็ก"],PENDING_PAYMENT:["PAID","ยืนยันเงิน"],PAID:["PACKING","เริ่มแพ็ก"],PACKING:["PACKED","ตรวจแพ็กแล้ว"],PACKED:["SHIP","จัดส่ง"]}[order.status];if(order.status==="SHIPPED")main=order.payment_method==="COD"&&!order.cod_received_at?["COD_RECEIVED","ยืนยันยอด COD"]:["COMPLETED","ปิดออเดอร์"];let html=`<button data-order-detail="${esc(order.id)}">ดู</button>`;if(main)html+=`<button data-order-action="${main[0]}" data-order-id="${esc(order.id)}">${main[1]}</button>`;if(!["SHIPPED","COMPLETED","CANCELLED"].includes(order.status))html+=`<button data-order-action="CANCELLED" data-order-id="${esc(order.id)}">ยกเลิก</button>`;return html}
function renderOrders(){const body=$("#orderRows");if(!body)return;body.innerHTML=state.orders.length?state.orders.map(order=>`<tr><td><b>${esc(order.id)}</b></td><td>${esc(order.customer_name)}<small class="muted">${esc(order.phone||"")}</small></td><td>${esc(order.source)}</td><td>${esc(order.payment_method)}</td><td><b>${money.format(order.total)}</b></td><td>${status(order.status)}</td><td>${date(order.created_at)}</td><td><div class="row-actions">${actions(order)}</div></td></tr>`).join(""):`<tr><td colspan="8">ยังไม่มีออเดอร์</td></tr>`}
function renderPayments(){const root=$("#paymentCards");if(!root)return;const rows=state.orders.filter(order=>order.status==="PENDING_PAYMENT");root.innerHTML=rows.length?rows.map(order=>`<article class="work-card"><h3>${esc(order.id)}</h3><p>${esc(order.customer_name)} · ${esc(order.phone)}</p><div class="total">${money.format(order.total)}</div><p>${date(order.created_at)}</p><footer><button class="button ghost" data-order-detail="${esc(order.id)}">ดูสลิป</button><button class="button orange" data-order-action="PAID" data-order-id="${esc(order.id)}">ยืนยันยอด</button></footer></article>`).join(""):`<article class="work-card"><h3>ไม่มีรายการรอตรวจ</h3><p>ออเดอร์ที่รอชำระเงินจะแสดงที่นี่</p></article>`}
function renderShipping(){const root=$("#shippingCards");if(!root)return;const rows=state.orders.filter(order=>order.status==="PACKED"||(order.status==="SHIPPED"&&order.payment_method==="COD"&&!order.cod_received_at));root.innerHTML=rows.length?rows.map(order=>{const awaitingCod=order.status==="SHIPPED";return`<article class="work-card"><h3>${esc(order.id)}</h3><p>${esc(order.customer_name)}<br>${esc(order.address||"")}</p><div class="total">${money.format(order.total)}</div>${awaitingCod?`<p class="status-PENDING_PAYMENT">รอยืนยันยอด COD${order.customer_received_at?" · ลูกค้ารับแล้ว":""}</p>`:""}<footer><button class="button ghost" data-order-detail="${esc(order.id)}">รายละเอียด</button><button class="button" data-order-action="${awaitingCod?"COD_RECEIVED":"SHIP"}" data-order-id="${esc(order.id)}">${awaitingCod?"ยืนยันยอด COD":"ใส่เลขพัสดุ"}</button></footer></article>`}).join(""):`<article class="work-card"><h3>ไม่มีรายการพร้อมส่ง</h3><p>ออเดอร์ที่ตรวจแพ็กแล้วหรือรอตรวจยอด COD จะแสดงที่นี่</p></article>`}
async function orderDetail(id){try{const order=(await api(`/api/admin/orders/${encodeURIComponent(id)}`)).order;const proof=order.payment_proof?`<h3>หลักฐานการชำระเงิน</h3><img src="${esc(order.payment_proof)}" alt="Payment proof" style="max-width:100%;max-height:420px;border-radius:12px">`:"",cod=order.payment_method==="COD"?`<p class="notice"><b>COD</b><br>ลูกค้ายืนยันรับ: ${order.customer_received_at?date(order.customer_received_at):"ยังไม่ยืนยัน"}<br>แอดมินยืนยันยอด: ${order.cod_received_at?date(order.cod_received_at):"ยังไม่ได้รับยอด"}</p>`:"";modal(`ออเดอร์ ${order.id}`,`<div class="modal-grid"><div><p><b>ลูกค้า</b><br>${esc(order.customer_name)} · ${esc(order.phone)}<br>${esc(order.address)}</p><p><b>ชำระเงิน</b> ${esc(order.payment_method)}<br><b>สถานะ</b> ${status(order.status)}</p></div><div><p><b>ยอดสินค้า</b> ${money.format(order.subtotal)}<br><b>ส่วนลด</b> ${money.format(order.discount)}<br><b>ค่าส่ง</b> ${money.format(order.shipping_fee)}<br><b>รวม</b> ${money.format(order.total)}</p><p><b>ขนส่ง</b> ${esc(order.tracking_company||"—")} ${esc(order.tracking_number||"")}</p></div></div>${cod}<div class="table-wrap"><table><thead><tr><th>สินค้า</th><th>จำนวน</th><th>ราคา/หน่วย</th><th>รวม</th></tr></thead><tbody>${order.items.map(item=>`<tr><td>${esc(item.product_name)}</td><td>${item.quantity} ${esc(item.unit)}</td><td>${money.format(item.unit_price)}</td><td>${money.format(item.line_total)}</td></tr>`).join("")}</tbody></table></div>${proof}<p><button class="button ghost" onclick="window.print()">พิมพ์/บันทึกบิล</button></p>`)}catch(error){toast(errorText(error))}}
async function transition(id,next,extra={}){if(next==="CANCELLED"&&!confirm("ยืนยันยกเลิกออเดอร์และคืนสต็อก?"))return;try{await api(`/api/admin/orders/${encodeURIComponent(id)}/transition`,{method:"POST",body:JSON.stringify({status:next,...extra})});toast("อัปเดตสถานะเรียบร้อย");closeModal();await Promise.all([loadOrders(),loadDashboard()])}catch(error){toast(errorText(error))}}
async function confirmCod(id){if(!confirm("ยืนยันว่าได้รับยอดเงิน COD จากบริษัทขนส่งแล้ว?"))return;try{await api(`/api/admin/orders/${encodeURIComponent(id)}/cod-received`,{method:"POST",body:"{}"});toast("ยืนยันยอด COD แล้ว สามารถปิดออเดอร์ได้");await Promise.all([loadOrders(),loadDashboard()])}catch(error){toast(errorText(error))}}
function shippingModal(id){modal("บันทึกการจัดส่ง",`<form id="shippingForm" class="form"><label>บริษัทขนส่ง<input id="trackingCompany" class="field" list="carrierList" required placeholder="เลือกหรือพิมพ์บริษัทขนส่ง"><datalist id="carrierList"><option value="Thailand Post"><option value="Kerry Express"><option value="Flash Express"><option value="J&T Express"><option value="SPX Express"><option value="Ninja Van"></datalist></label><label>เลขพัสดุ<input id="trackingNumber" class="field" required autocomplete="off" placeholder="กรอกเลขพัสดุ"></label><p class="notice">ลูกค้าจะเห็นปุ่มติดตาม คัดลอก และแชร์เลขพัสดุทันที</p><button class="button" type="submit">ยืนยันจัดส่ง</button></form>`);$("#shippingForm").onsubmit=event=>{event.preventDefault();transition(id,"SHIPPED",{trackingCompany:$("#trackingCompany").value,trackingNumber:$("#trackingNumber").value})}}

async function loadProducts(){try{state.products=(await api("/api/admin/products")).products;renderProductTable();renderProductPicker();renderPosProducts()}catch(error){toast(errorText(error))}}
function tiers(product){const entries=Object.entries(product.prices||{}).map(([size,price])=>[Number(size),Number(price)]).filter(([size,price])=>size>0&&Number.isFinite(price)).sort((a,b)=>a[0]-b[0]);return entries.length?entries:[[1,Number(product.price||0)]]}
function renderPosProducts(){const root=$("#posProducts");if(!root)return;const term=$("#posSearch").value.trim().toLowerCase(),rows=state.products.filter(product=>product.status==="ACTIVE"&&(!term||product.name.toLowerCase().includes(term)||product.category.toLowerCase().includes(term))).slice(0,100);root.innerHTML=rows.map(product=>`<article class="pick-card">${product.images?.[0]?`<img src="${esc(product.images[0])}" alt="${esc(product.name)}">`:`<img src="/assets/jigz-planet.png" alt="">`}<div><h3>${esc(product.name)}</h3><small>คงเหลือ ${Number(product.stock||0)} ${esc(product.unit)}</small><select id="tier-${esc(product.id)}" class="field">${tiers(product).map(([size,price])=>`<option value="${size}">${size} ${esc(product.unit)} · ${money.format(price)}</option>`).join("")}</select><button class="button small wide" data-pos-add="${esc(product.id)}">เพิ่ม</button></div></article>`).join("")}
function addPos(id){const product=state.products.find(item=>item.id===id),packSize=Number(document.getElementById(`tier-${id}`)?.value||1),key=`${id}|${packSize}`,line=state.posCart.find(item=>item.key===key);if(line)line.qty+=1;else state.posCart.push({key,productId:id,packSize,qty:1});renderPosCart()}
function renderPosCart(){const root=$("#posCart");let total=0;root.innerHTML=state.posCart.length?state.posCart.map(line=>{const product=state.products.find(item=>item.id===line.productId),price=Number(product?.prices?.[String(line.packSize)]??product?.price??0);total+=price*line.qty;return`<div class="cart-line"><div><b>${esc(product?.name)}</b><small>${line.packSize} ${esc(product?.unit)} × ${line.qty}</small></div><b>${money.format(price*line.qty)}</b><div class="row-actions"><button data-pos-qty="-1" data-pos-key="${esc(line.key)}">−</button><button data-pos-qty="1" data-pos-key="${esc(line.key)}">+</button></div></div>`}).join(""):"";$("#posTotal").textContent=money.format(total)}
function renderProductPicker(){const select=$("#receiveProduct");if(!select)return;select.innerHTML=`<option value="">เลือกสินค้า</option>`+state.products.map(product=>`<option value="${esc(product.id)}">${esc(product.name)} · เหลือ ${Number(product.stock||0)} ${esc(product.unit)}</option>`).join("")}
function renderProductTable(){const root=$("#productRows");if(!root)return;const term=$("#productSearch").value.trim().toLowerCase(),rows=state.products.filter(product=>!term||product.name.toLowerCase().includes(term)||product.id.toLowerCase().includes(term));root.innerHTML=rows.map(product=>`<tr><td><b>${esc(product.name)}</b><small class="muted">${esc(product.id)}</small></td><td>${esc(product.category)}</td><td>${esc(product.unit)}</td><td>${money.format(product.price||0)}</td><td>${product.latest_cost===null||product.latest_cost===undefined?'<span class="muted">ยังไม่บันทึก</span>':money.format(product.latest_cost)}</td><td><b>${Number(product.stock||0)}</b></td><td>${product.status==="ACTIVE"?'<span class="badge">ACTIVE</span>':'INACTIVE'}</td><td><div class="row-actions"><button class="button ghost small" data-product-cost="${esc(product.id)}">＋ ทุน/สต็อก</button><button class="button ghost small" data-product-edit="${esc(product.id)}">แก้ไข</button>${state.user?.role==="OWNER"?`<button class="delete-control" data-product-delete="${esc(product.id)}" aria-label="ลบ ${esc(product.name)}" title="ลบสินค้า">×</button>`:""}</div></td></tr>`).join("")}
const DEFAULT_CATEGORIES=["TOP","POP","TRIM","EDIBLES","ACCESSORIES","OTHER"];
function categoryOptions(current=""){const categories=[...new Set([...DEFAULT_CATEGORIES,...state.products.map(product=>product.category),current].filter(Boolean))].sort((a,b)=>a.localeCompare(b,"th"));return`<option value="">เลือกหมวดหมู่</option>`+categories.map(category=>`<option value="${esc(category)}" ${category===current?"selected":""}>${esc(category)}</option>`).join("")}
function priceTierRow(size="",price=""){return`<div class="price-tier-row"><label><span>จำนวน</span><input class="field" data-tier-size type="number" min="0.001" step="0.001" value="${esc(size)}" placeholder="เช่น 5"></label><label><span>ราคารวม (บาท)</span><input class="field" data-tier-price type="number" min="0" step="0.01" value="${esc(price)}" placeholder="เช่น 350"></label><button type="button" class="tier-remove" data-tier-remove aria-label="ลบขนาดราคานี้">×</button></div>`}
function priceTierEditor(prefix,prices={}){const rows=Object.entries(prices).filter(([size,price])=>Number(size)!==1&&Number(size)>0&&Number(price)>=0).sort((a,b)=>Number(a[0])-Number(b[0]));return`<section class="price-tier-editor"><header><div><b>ราคาขายตามขนาด</b><small>ราคา 1G ใช้จากช่องราคาขายเริ่มต้น เพิ่มราคาเรทอื่นด้านล่างโดยไม่ต้องเขียนโค้ด</small></div><div class="tier-actions"><button type="button" class="button ghost small tier-preset" data-tier-preset="${prefix}">ใช้เรท 1G–1000G</button><button type="button" class="button ghost small" data-tier-add="${prefix}">＋ เพิ่มขนาด</button></div></header><div class="standard-tier-note"><b>เรทมาตรฐาน:</b> 1G / 10G / 30G / 50G / 100G / 500G / 1000G</div><div id="${prefix}TierRows" class="price-tier-rows">${rows.map(([size,price])=>priceTierRow(size,price)).join("")}</div><p id="${prefix}TierSummary" class="tier-summary">ยังไม่มีราคาขนาดพิเศษ</p></section>`}
function updatePriceTierSummary(prefix){const root=$(`#${prefix}TierRows`),summary=$(`#${prefix}TierSummary`);if(!root||!summary)return;const complete=[...root.querySelectorAll(".price-tier-row")].filter(row=>row.querySelector("[data-tier-size]").value&&row.querySelector("[data-tier-price]").value);summary.textContent=complete.length?`เพิ่มราคาขนาดพิเศษแล้ว ${complete.length} รายการ · ระบบจะเรียงจำนวนให้อัตโนมัติ`:"ยังไม่มีราคาขนาดพิเศษ"}
function bindPriceTierEditor(prefix){const root=$(`#${prefix}TierRows`),add=document.querySelector(`[data-tier-add="${prefix}"]`),preset=document.querySelector(`[data-tier-preset="${prefix}"]`);if(!root||!add)return;add.onclick=()=>{root.insertAdjacentHTML("beforeend",priceTierRow());root.querySelector(".price-tier-row:last-child [data-tier-size]")?.focus();updatePriceTierSummary(prefix)};if(preset)preset.onclick=()=>{const existing=new Set([...root.querySelectorAll("[data-tier-size]")].map(input=>Number(input.value)));for(const size of[10,30,50,100,500,1000])if(!existing.has(size))root.insertAdjacentHTML("beforeend",priceTierRow(size,""));updatePriceTierSummary(prefix);root.querySelector("[data-tier-price]")?.focus();toast("เพิ่มเรทมาตรฐานแล้ว กรุณาใส่ราคาแต่ละขนาด")};root.addEventListener("click",event=>{if(!event.target.closest("[data-tier-remove]"))return;event.target.closest(".price-tier-row").remove();updatePriceTierSummary(prefix)});root.addEventListener("input",()=>updatePriceTierSummary(prefix));updatePriceTierSummary(prefix)}
function readPriceTiers(prefix,basePriceId){const base=Number($(`#${basePriceId}`).value),result={"1":base},seen=new Set(["1"]);for(const row of document.querySelectorAll(`#${prefix}TierRows .price-tier-row`)){const sizeInput=row.querySelector("[data-tier-size]"),priceInput=row.querySelector("[data-tier-price]"),sizeRaw=sizeInput.value.trim(),priceRaw=priceInput.value.trim();row.classList.remove("invalid");if(!sizeRaw&&!priceRaw)continue;const size=Number(sizeRaw),price=Number(priceRaw),key=String(size);if(!sizeRaw||!priceRaw||!Number.isFinite(size)||size<=0||!Number.isFinite(price)||price<0||seen.has(key)){row.classList.add("invalid");throw new Error("invalid_price_tier_form")}seen.add(key);result[key]=price}return Object.fromEntries(Object.entries(result).sort((a,b)=>Number(a[0])-Number(b[0])))}
function productImageUploader(prefix,existing=[]){return`<section class="product-uploader"><label class="upload-button" for="${prefix}Files">＋ เลือกรูปจากเครื่อง</label><input id="${prefix}Files" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><small>เลือกได้สูงสุด 5 รูป · ระบบจะย่อรูปให้อัตโนมัติ</small><div id="${prefix}NewPreview" class="image-preview"></div>${existing.length?`<p class="muted">รูปปัจจุบัน — เอาเครื่องหมายออกเพื่อลบ</p><div class="image-preview">${existing.map((image,index)=>`<label class="image-tile"><img src="${esc(image)}" alt="รูปสินค้า ${index+1}"><input type="checkbox" data-existing-image="${prefix}" value="${index}" checked><span>เก็บรูปนี้</span></label>`).join("")}</div>`:""}<details><summary>เพิ่มรูปด้วย URL (ไม่บังคับ)</summary><textarea id="${prefix}Urls" class="field" placeholder="https://... แยกบรรทัด"></textarea></details></section>`}
function bindProductUpload(prefix){const input=$(`#${prefix}Files`),preview=$(`#${prefix}NewPreview`);input.onchange=()=>{for(const url of input._previewUrls||[])URL.revokeObjectURL(url);input._previewUrls=[...input.files].map(file=>URL.createObjectURL(file));preview.innerHTML=input._previewUrls.map((url,index)=>`<div class="image-tile"><img src="${esc(url)}" alt="รูปใหม่ ${index+1}"><span>รูปใหม่ ${index+1}</span></div>`).join("");if(input.files.length>5)toast("ใส่รูปสินค้าได้สูงสุด 5 รูป")}}
async function productImageData(file){if(!["image/jpeg","image/png","image/webp"].includes(file.type))throw new Error("invalid_image");let maxWidth=1200,quality=.82,data="";for(let attempt=0;attempt<6;attempt++){data=await imageData(file,maxWidth,quality,"image/webp");if(data.length<=230000)return data;maxWidth=Math.round(maxWidth*.82);quality=Math.max(.5,quality-.08)}throw new Error("image_too_large")}
async function collectProductImages(prefix,existing=[]){const kept=[...document.querySelectorAll(`[data-existing-image="${prefix}"]:checked`)].map(input=>existing[Number(input.value)]).filter(Boolean),urls=$(`#${prefix}Urls`).value.split("\n").map(value=>value.trim()).filter(Boolean),files=[...$(`#${prefix}Files`).files];if(kept.length+urls.length+files.length>5)throw new Error("too_many_images");const uploads=[];for(const file of files)uploads.push(await productImageData(file));return[...new Set([...kept,...urls,...uploads])].slice(0,5)}
function newProduct(){modal("เพิ่มสินค้า",`<form id="newProductForm" class="form product-data-form"><section class="product-form-guide"><b>กรอกข้อมูลสินค้า</b><span>ช่องที่มีเครื่องหมาย * จำเป็นต้องกรอก</span></section><div class="two"><label class="field-label"><span>รหัสสินค้า</span><small>เว้นว่างได้ ระบบจะสร้างรหัสให้อัตโนมัติ</small><input id="newProductId" class="field" placeholder="ตัวอย่าง JIGZ-0001"></label><label class="field-label"><span>แบรนด์สินค้า *</span><small>ชื่อแบรนด์ที่แสดงในระบบ</small><input id="newBrand" class="field" value="JIGz" required placeholder="ตัวอย่าง JIGz"></label></div><label class="field-label"><span>ชื่อสินค้า *</span><small>ชื่อที่ลูกค้าจะเห็นในหน้าร้าน</small><input id="newName" class="field" required placeholder="กรอกชื่อสินค้า"></label><div class="two"><label class="field-label"><span>หมวดหมู่สินค้า *</span><small>ใช้สำหรับจัดกลุ่มและค้นหา</small><select id="newCategory" class="field" required>${categoryOptions()}</select></label><label class="field-label"><span>หน่วยนับสินค้า *</span><small>เช่น กรัม ชิ้น ซอง หรือกระปุก</small><select id="newUnit" class="field" required><option value="">เลือกหน่วย</option><option value="g.">g. / กรัม</option><option value="ชิ้น">ชิ้น</option><option value="ซอง">ซอง</option><option value="กระปุก">กระปุก</option><option value="อัน">อัน</option><option value="ตัว">ตัว</option></select></label></div><div class="three"><label class="field-label"><span>ราคาขายเริ่มต้น *</span><small>ราคาขายต่อ 1 หน่วย</small><input id="newPrice" class="field" type="number" min="0" step="0.01" required placeholder="0.00"></label><label class="field-label"><span>สต็อกเริ่มต้น</span><small>จำนวนสินค้าที่มีอยู่ตอนนี้</small><input id="newStock" class="field" type="number" min="0" step="0.001" value="0" placeholder="0"></label><label class="field-label"><span>ต้นทุนต่อหน่วย</span><small>ใช้คำนวณกำไรและค่าคอม</small><input id="newUnitCost" class="field" type="number" min="0" step="0.01" value="0" placeholder="0.00"></label></div><p class="notice">ตัวอย่าง: ถ้าหน่วยเป็นกรัม สต็อก 100 และต้นทุนต่อหน่วย 20 หมายถึงมีสินค้า 100 กรัม ต้นทุนกรัมละ 20 บาท</p>${priceTierEditor("newProduct")} ${productImageUploader("newProduct")}<button id="newProductSubmit" class="button" type="submit">สร้างสินค้า</button></form>`);bindProductUpload("newProduct");bindPriceTierEditor("newProduct");$("#newUnit").addEventListener("change",event=>{if(event.target.value==="g."&&!$("#newProductTierRows").children.length)document.querySelector('[data-tier-preset="newProduct"]')?.click()});$("#newProductForm").onsubmit=async event=>{event.preventDefault();const submit=$("#newProductSubmit");try{submit.disabled=true;submit.textContent="กำลังเตรียมรูป...";const prices=readPriceTiers("newProduct","newPrice"),images=await collectProductImages("newProduct");submit.textContent="กำลังบันทึก...";await api("/api/admin/products",{method:"POST",body:JSON.stringify({id:$("#newProductId").value,brand:$("#newBrand").value,name:$("#newName").value,category:$("#newCategory").value,unit:$("#newUnit").value,price:$("#newPrice").value,stock:$("#newStock").value,unitCost:$("#newUnitCost").value,prices,images})});toast("สร้างสินค้า รูป และต้นทุนตั้งต้นแล้ว");closeModal();await loadProducts()}catch(error){submit.disabled=false;submit.textContent="สร้างสินค้า";toast(errorText(error))}}}
function editProduct(id){const product=state.products.find(item=>item.id===id);if(!product)return;modal("แก้ไขสินค้า",`<form id="productForm" class="form product-data-form"><section class="product-form-guide"><b>แก้ไขข้อมูลสินค้า</b><span>รหัสสินค้า ${esc(product.id)} ไม่สามารถเปลี่ยนได้</span></section><label class="field-label"><span>ชื่อสินค้า *</span><small>ชื่อที่แสดงในหน้าร้าน</small><input id="editName" class="field" value="${esc(product.name)}" required></label><div class="two"><label class="field-label"><span>หมวดหมู่สินค้า *</span><small>กลุ่มสำหรับค้นหาและกรอง</small><select id="editCategory" class="field" required>${categoryOptions(product.category)}</select></label><label class="field-label"><span>หน่วยนับสินค้า *</span><small>หน่วยที่ใช้ขายและตัดสต็อก</small><select id="editUnit" class="field" required><option value="${esc(product.unit)}" selected>${esc(product.unit)}</option>${["g.","ชิ้น","ซอง","กระปุก","อัน","ตัว"].filter(unit=>unit!==product.unit).map(unit=>`<option value="${unit}">${unit}</option>`).join("")}</select></label></div><div class="three"><label class="field-label"><span>ราคาขายเริ่มต้น *</span><small>ราคาต่อ 1 หน่วย</small><input id="editPrice" class="field" type="number" min="0" step="0.01" value="${Number(product.price||0)}" required></label><label class="field-label"><span>สต็อกปัจจุบัน *</span><small>จำนวนคงเหลือในระบบ</small><input id="editStock" class="field" type="number" min="0" step="0.001" value="${Number(product.stock||0)}" required></label><label class="field-label"><span>สถานะสินค้า</span><small>ACTIVE แสดงหน้าร้าน</small><select id="editStatus" class="field"><option value="ACTIVE" ${product.status==="ACTIVE"?"selected":""}>ACTIVE · เปิดขาย</option><option value="INACTIVE" ${product.status!=="ACTIVE"?"selected":""}>INACTIVE · ซ่อนสินค้า</option></select></label></div>${priceTierEditor("editProduct",product.prices||{})}${productImageUploader("editProduct",product.images||[])}<button id="editProductSubmit" class="button" type="submit">บันทึกสินค้า</button></form>`);bindProductUpload("editProduct");bindPriceTierEditor("editProduct");$("#productForm").onsubmit=async event=>{event.preventDefault();const submit=$("#editProductSubmit");try{submit.disabled=true;submit.textContent="กำลังเตรียมรูป...";const prices=readPriceTiers("editProduct","editPrice"),images=await collectProductImages("editProduct",product.images||[]);submit.textContent="กำลังบันทึก...";await api(`/api/admin/products/${encodeURIComponent(id)}`,{method:"POST",body:JSON.stringify({name:$("#editName").value,category:$("#editCategory").value,unit:$("#editUnit").value,price:$("#editPrice").value,stock:$("#editStock").value,status:$("#editStatus").value,prices,images})});toast("บันทึกสินค้าและรูปแล้ว");closeModal();await loadProducts()}catch(error){submit.disabled=false;submit.textContent="บันทึกสินค้า";toast(errorText(error))}}}
function focusProductCost(id){showView("products");$("#receiveProduct").value=id;$("#receiveStockPanel").scrollIntoView({behavior:"smooth",block:"center"});$("#receiveQty").focus();toast("กรอกจำนวนรับเข้าและต้นทุนต่อหน่วย")}
async function deleteProduct(id){const product=state.products.find(item=>item.id===id);if(!product||state.user?.role!=="OWNER")return toast("รายการนี้ทำได้เฉพาะ OWNER");if(!confirm(`ลบสินค้า “${product.name}” ออกจากระบบ?\nประวัติออเดอร์เดิมจะยังคงอยู่`))return;if(!confirm("ยืนยันครั้งสุดท้าย: ต้องการลบสินค้านี้จริงหรือไม่?"))return;try{const result=await api(`/api/admin/products/${encodeURIComponent(id)}`,{method:"DELETE"});toast(result.archived?"นำสินค้าออกแล้ว และเก็บประวัติออเดอร์ไว้":"ลบสินค้าแล้ว");await Promise.all([loadProducts(),loadDashboard()])}catch(error){toast(errorText(error))}}

async function loadUsers(){try{state.users=(await api("/api/admin/users")).users;$("#userRows").innerHTML=state.users.map(user=>{const online=Date.now()-new Date(String(user.last_seen_at).replace(" ","T")+"Z").getTime()<300000,canDelete=state.user?.role==="OWNER"&&user.role!=="OWNER"&&user.id!==state.user.id;return`<tr><td><b>${esc(user.full_name||user.display_name)}</b><small class="muted">${esc(user.id)}</small></td><td>${esc(user.phone||"—")}</td><td class="wrap">${esc(user.address||"—")}</td><td><b>${Number(user.points||0)}</b></td><td>${online?'<b class="green">● ONLINE</b>':'OFFLINE'}</td><td>${date(user.last_seen_at)}</td><td><div class="row-actions"><button class="button ghost small" data-points-user="${esc(user.id)}">ปรับแต้ม</button>${canDelete?`<button class="delete-control" data-user-delete="${esc(user.id)}" data-user-source="customers" aria-label="ลบลูกค้า" title="ลบลูกค้า">×</button>`:""}</div></td></tr>`}).join("")}catch(error){toast(errorText(error))}}
async function loadStaff(){if(state.user?.role!=="OWNER")return;try{const result=await api("/api/admin/staff");state.staff=result.users;state.ownerRequests=result.ownerRequests||[];$("#secondaryOwnerCount").textContent=`${result.secondaryOwnerCount} / ${result.secondaryOwnerLimit}`;$("#ownerDeletePending").textContent=state.ownerRequests.filter(item=>item.status==="PENDING").length;$("#myOwnerType").textContent=result.isPrimaryOwner?"OWNER หลัก":"OWNER รอง";renderStaff();renderOwnerRequests(result.isPrimaryOwner)}catch(error){toast(errorText(error))}}
function renderOwnerRequests(isPrimaryOwner){const panel=$("#ownerRequestPanel"),root=$("#ownerRequestCards"),rows=state.ownerRequests.filter(item=>item.status==="PENDING");panel.classList.toggle("hidden",!rows.length);root.innerHTML=rows.map(item=>`<article class="owner-request-card"><div><span class="role-badge role-OWNER">รอยืนยัน</span><b>ขอลบ ${esc(item.target_name)}</b><small>ส่งโดย ${esc(item.requested_by_name)} · ${date(item.created_at)}</small></div>${isPrimaryOwner?`<div class="row-actions"><button class="button danger small" data-owner-review="REJECTED" data-owner-request="${esc(item.id)}">ปฏิเสธ</button><button class="button small" data-owner-review="APPROVED" data-owner-request="${esc(item.id)}">ยืนยันลบ</button></div>`:'<span class="muted">รอ OWNER หลัก</span>'}</article>`).join("")}
function renderStaff(){const root=$("#staffRows");if(!root)return;const term=$("#staffSearch").value.trim().toLowerCase(),role=$("#staffRoleFilter").value,rows=state.staff.filter(user=>(!term||`${user.full_name||""} ${user.display_name} ${user.phone||""} ${user.id}`.toLowerCase().includes(term))&&(!role||user.role===role));root.innerHTML=rows.length?rows.map(user=>{const online=Date.now()-new Date(String(user.last_seen_at).replace(" ","T")+"Z").getTime()<300000,owner=user.role==="OWNER",primary=Boolean(user.is_primary_owner),admin=user.role==="ADMIN",pending=state.ownerRequests.some(item=>item.target_user_id===user.id&&item.status==="PENDING"),canDirectDelete=!owner&&user.id!==state.user?.id,canPromoteOwner=Boolean(state.user?.is_primary_owner)&&!owner;let controls="";if(primary)controls='<span class="primary-owner-lock">◆ OWNER หลัก</span>';else if(owner)controls=`<button class="button danger small" data-user-delete="${esc(user.id)}" data-user-source="staff" ${pending?"disabled":""}>${pending?"รอการยืนยัน":"ส่งคำขอลบ"}</button>`;else controls=`${admin?`<button class="button danger small" data-staff-role="CUSTOMER" data-staff-id="${esc(user.id)}">ถอดสิทธิ์</button>`:`<button class="button small" data-staff-role="ADMIN" data-staff-id="${esc(user.id)}">แต่งตั้งแอดมิน</button>`}${canPromoteOwner?`<button class="button owner-button small" data-staff-role="OWNER" data-staff-id="${esc(user.id)}">ตั้ง OWNER รอง</button>`:""}${canDirectDelete?`<button class="delete-control" data-user-delete="${esc(user.id)}" data-user-source="staff" aria-label="ลบผู้ใช้" title="ลบผู้ใช้">×</button>`:""}`;const roleLabel=primary?"OWNER หลัก":owner?"OWNER รอง":admin?"ADMIN":"CUSTOMER";return`<tr><td><b>${esc(user.full_name||user.display_name)}</b><small class="muted">${esc(user.id)}</small></td><td>${esc(user.phone||"—")}</td><td><span class="role-badge role-${primary?"PRIMARY":esc(user.role)}">${roleLabel}</span></td><td>${online?'<b class="green">● ONLINE</b>':'OFFLINE'}</td><td>${date(user.last_seen_at)}</td><td><div class="row-actions">${controls}</div></td></tr>`}).join(""):`<tr><td colspan="6">ไม่พบผู้ใช้</td></tr>`}
async function changeStaffRole(userId,role){const user=state.staff.find(item=>item.id===userId),verb=role==="OWNER"?"แต่งตั้ง OWNER รอง":role==="ADMIN"?"แต่งตั้งแอดมิน":"ถอดสิทธิ์แอดมิน";if(!user||!confirm(`${verb} ให้ ${user.full_name||user.display_name}?${role==="OWNER"?"\n\nOWNER รองมีสิทธิ์ดูแลระบบและส่งคำขอลบ OWNER ได้":""}`))return;try{await api(`/api/admin/staff/${encodeURIComponent(userId)}/role`,{method:"POST",body:JSON.stringify({role})});toast(`${verb}เรียบร้อย`);await loadStaff()}catch(error){toast(errorText(error))}}
async function deleteUser(userId,source){const user=[...state.users,...state.staff].find(item=>item.id===userId),name=user?.full_name||user?.display_name||userId,owner=user?.role==="OWNER";if(!confirm(owner?`ส่งคำขอลบ OWNER รอง ${name}?\n\nระบบจะรอ OWNER หลักกดยืนยันก่อน จึงจะลบบัญชีจริง`:`ลบ ${name} ออกจากระบบ?\n\nประวัติออเดอร์และ Audit จะยังคงอยู่ แต่บัญชีนี้จะออกจากระบบทุกอุปกรณ์`))return;try{const result=await api(`/api/admin/users/${encodeURIComponent(userId)}`,{method:"DELETE"});toast(result.approvalRequired?result.alreadyPending?"มีคำขอนี้รอ OWNER หลักอยู่แล้ว":"ส่งคำขอให้ OWNER หลักยืนยันแล้ว":"ลบผู้ใช้และยกเลิก Session แล้ว");if(source==="staff")await Promise.all([loadStaff(),loadUsers()]);else await loadUsers()}catch(error){toast(errorText(error))}}
async function reviewOwnerDeletion(requestId,status){const approve=status==="APPROVED";if(!confirm(approve?"OWNER หลักยืนยันลบ OWNER รองคนนี้?\n\nบัญชีจะออกจากระบบทุกอุปกรณ์ แต่ประวัติจะยังคงอยู่":"ปฏิเสธคำขอลบ OWNER นี้?"))return;try{await api(`/api/admin/owner-deletion-requests/${encodeURIComponent(requestId)}/review`,{method:"POST",body:JSON.stringify({status})});toast(approve?"OWNER หลักยืนยันและลบบัญชีแล้ว":"ปฏิเสธคำขอแล้ว");await Promise.all([loadStaff(),loadUsers()])}catch(error){toast(errorText(error))}}
function pointsModal(userId){const user=state.users.find(item=>item.id===userId);modal("ปรับแต้มลูกค้า",`<p>${esc(user?.full_name||user?.display_name)} · แต้มปัจจุบัน ${Number(user?.points||0)}</p><form id="pointsForm" class="form"><input id="pointsAmount" class="field" type="number" step="1" required placeholder="จำนวน เช่น 10 หรือ -5"><input id="pointsReason" class="field" required placeholder="เหตุผล"><button class="button" type="submit">บันทึกแต้ม</button></form>`);$("#pointsForm").onsubmit=async event=>{event.preventDefault();try{await api("/api/admin/points/adjust",{method:"POST",body:JSON.stringify({userId,points:$("#pointsAmount").value,reason:$("#pointsReason").value})});toast("ปรับแต้มแล้ว");closeModal();await loadUsers()}catch(error){toast(errorText(error))}}}

async function loadAgents(){try{const [agents,commissions,users]=await Promise.all([api("/api/admin/agents"),api("/api/admin/commissions"),state.users.length?Promise.resolve({users:state.users}):api("/api/admin/users")]);state.agents=agents.agents;state.commissions=commissions.commissions;state.users=users.users;$("#agentUserList").innerHTML=state.users.map(user=>`<option value="${esc(user.id)}">${esc(user.full_name||user.display_name)} · ${esc(user.phone||"ไม่มีเบอร์")}</option>`).join("");$("#agentRows").innerHTML=state.agents.map(agent=>`<tr><td><b>${esc(agent.code)}</b></td><td>${esc(agent.name)}</td><td>${agent.agent_type==="RESELLER"?"ตัวแทนจำหน่าย":"เด็กส่งยอด"}</td><td>${agent.user_id?`<b class="green">เชื่อมแล้ว</b><small class="muted wallet-user-id">${esc(agent.user_id)}</small>`:'<span class="muted">ยังไม่เชื่อม</span>'}</td><td>${Number(agent.commission_rate).toFixed(2)}%</td><td>${esc(agent.status)}</td><td><div class="row-actions"><button class="button ghost small" data-agent-edit="${agent.id}">แก้ไข</button>${state.user?.role==="OWNER"?`<button class="delete-control" data-agent-delete="${agent.id}" title="ลบตัวแทน">×</button>`:""}</div></td></tr>`).join("");$("#commissionRows").innerHTML=state.commissions.length?state.commissions.map(item=>`<tr><td>${esc(item.order_id)}</td><td>${esc(item.agent_code)} · ${esc(item.agent_name)}</td><td>${money.format(item.revenue_net)}</td><td>${money.format(item.actual_cost)}</td><td>${money.format(item.profit_base)}</td><td>${Number(item.commission_rate).toFixed(2)}%</td><td><b>${money.format(item.commission_amount)}</b></td><td>${esc(item.status)}</td><td><div class="row-actions"><button class="button ghost small" data-commission-edit="${item.id}">แก้ไข</button>${state.user?.role==="OWNER"?`<button class="delete-control" data-commission-delete="${item.id}" title="ลบค่าคอม">×</button>`:""}</div></td></tr>`).join(""):`<tr><td colspan="9">ยังไม่มีค่าคอม</td></tr>`}catch(error){toast(errorText(error))}}
function editAgent(id){const agent=state.agents.find(item=>Number(item.id)===Number(id));if(!agent)return;modal(`แก้ไขตัวแทน ${agent.code}`,`<form id="editAgentForm" class="form"><input id="editAgentName" class="field" value="${esc(agent.name)}" required><input id="editAgentUserId" class="field" list="editAgentUserList" value="${esc(agent.user_id||"")}" placeholder="User ID สำหรับรับเครดิต"><datalist id="editAgentUserList">${state.users.map(user=>`<option value="${esc(user.id)}">${esc(user.full_name||user.display_name)} · ${esc(user.phone||"ไม่มีเบอร์")}</option>`).join("")}</datalist><div class="three"><select id="editAgentType" class="field"><option value="RESELLER" ${agent.agent_type==="RESELLER"?"selected":""}>ตัวแทนจำหน่าย</option><option value="SALES" ${agent.agent_type==="SALES"?"selected":""}>เด็กส่งยอด</option></select><input id="editAgentRate" class="field" type="number" min="0" max="100" step="0.01" value="${Number(agent.commission_rate)}" required><select id="editAgentStatus" class="field"><option value="ACTIVE" ${agent.status==="ACTIVE"?"selected":""}>เปิดใช้งาน</option><option value="INACTIVE" ${agent.status!=="ACTIVE"?"selected":""}>ระงับ</option></select></div><p class="notice">รหัส ${esc(agent.code)} จะคงเดิม ค่าคอมจะจ่ายเข้ากระเป๋าของ User ID ที่เชื่อมไว้</p><button class="button" type="submit">บันทึกตัวแทน</button></form>`);$("#editAgentForm").onsubmit=async event=>{event.preventDefault();try{await api(`/api/admin/agents/${agent.id}`,{method:"POST",body:JSON.stringify({name:$("#editAgentName").value,userId:$("#editAgentUserId").value,agentType:$("#editAgentType").value,commissionRate:$("#editAgentRate").value,status:$("#editAgentStatus").value})});toast("แก้ไขตัวแทนและกระเป๋ารับค่าคอมแล้ว");closeModal();await loadAgents()}catch(error){toast(errorText(error))}}}
async function deleteAgent(id){const agent=state.agents.find(item=>Number(item.id)===Number(id));if(!agent||!confirm(`ลบตัวแทน ${agent.code} · ${agent.name}?`))return;try{const result=await api(`/api/admin/agents/${id}`,{method:"DELETE"});toast(result.archived?"นำตัวแทนออกแล้ว และเก็บประวัติเดิมไว้":"ลบตัวแทนแล้ว");await loadAgents()}catch(error){toast(errorText(error))}}
function editCommission(id){const item=state.commissions.find(row=>Number(row.id)===Number(id));if(!item)return;if(item.status==="PAID")return modal(`ค่าคอม ${item.order_id}`,`<p class="notice success">รายการนี้จ่ายเข้ากระเป๋าตัวแทนแล้ว ยอดและประวัติธุรกรรมถูกล็อกเพื่อความถูกต้องทางการเงิน</p><p>ค่าคอม <b>${money.format(item.commission_amount)}</b></p>`);modal(`แก้ไขค่าคอม ${item.order_id}`,`<form id="editCommissionForm" class="form"><p>ฐานกำไรหลังหักต้นทุนจริง <b>${money.format(item.profit_base)}</b></p><div class="two"><label>อัตราค่าคอม %<input id="editCommissionRate" class="field" type="number" min="0" max="100" step="0.01" value="${Number(item.commission_rate)}" required></label><label>สถานะ<select id="editCommissionStatus" class="field"><option value="PENDING" ${item.status==="PENDING"?"selected":""}>รอดำเนินการ</option><option value="APPROVED" ${item.status==="APPROVED"?"selected":""}>อนุมัติ</option><option value="REVERSED" ${item.status==="REVERSED"?"selected":""}>ยกเลิก/กลับรายการ</option></select></label></div><p class="notice">ระบบจะคำนวณยอดใหม่จากฐานกำไร × อัตราค่าคอม ใช้ปุ่ม “จ่ายค่าคอมตอนนี้” ในหน้าเครดิตเพื่อโอนเข้ากระเป๋า</p><button class="button" type="submit">บันทึกค่าคอม</button></form>`);$("#editCommissionForm").onsubmit=async event=>{event.preventDefault();try{await api(`/api/admin/commissions/${item.id}`,{method:"POST",body:JSON.stringify({commissionRate:$("#editCommissionRate").value,status:$("#editCommissionStatus").value})});toast("แก้ไขค่าคอมแล้ว");closeModal();await loadAgents()}catch(error){toast(errorText(error))}}}
async function deleteCommission(id){const item=state.commissions.find(row=>Number(row.id)===Number(id));if(!item||!confirm(`ลบรายการค่าคอมของออเดอร์ ${item.order_id}?`))return;try{await api(`/api/admin/commissions/${id}`,{method:"DELETE"});toast("ลบรายการค่าคอมแล้ว");await loadAgents()}catch(error){toast(errorText(error))}}

const walletStatusLabel={PENDING:"รอตรวจ",APPROVED:"อนุมัติแล้ว",REJECTED:"ไม่อนุมัติ"};
async function loadWalletRequests(){try{const query=new URLSearchParams();if($("#walletStatusFilter").value)query.set("status",$("#walletStatusFilter").value);if($("#walletTypeFilter").value)query.set("type",$("#walletTypeFilter").value);state.walletRequests=(await api(`/api/admin/wallet/requests?${query}`)).requests;const pending=state.walletRequests.filter(item=>item.status==="PENDING"),deposits=state.walletRequests.filter(item=>item.type==="DEPOSIT"&&item.status==="APPROVED").reduce((sum,item)=>sum+item.amount,0),withdrawals=state.walletRequests.filter(item=>item.type==="WITHDRAWAL"&&item.status==="APPROVED").reduce((sum,item)=>sum+item.amount,0);$("#walletPill").textContent=pending.length;$("#wPending").textContent=pending.length;$("#wDeposits").textContent=money.format(deposits);$("#wWithdrawals").textContent=money.format(withdrawals);$("#walletRequestCards").innerHTML=state.walletRequests.length?state.walletRequests.map(walletRequestCard).join(""):'<p class="muted">ไม่พบคำขอตามตัวกรอง</p>'}catch(error){toast(errorText(error))}}
function walletRequestCard(item){const isDeposit=item.type==="DEPOSIT",customer=esc(item.full_name||item.display_name),detail=isDeposit?`${item.proof_image?`<button class="wallet-proof" type="button" data-wallet-proof="${item.id}"><img src="${esc(item.proof_image)}" alt="สลิป ${esc(item.id)}"><span>แตะเพื่อดูสลิปเต็ม</span></button>`:'<div class="wallet-proof-empty">ไม่มีรูปสลิป</div>'}<div class="wallet-verify"><b>${esc(item.verification_status||"รอตรวจ")}</b><span>${esc(item.provider_message||"รอแอดมินตรวจสอบ")}</span></div>`:`<div class="withdraw-bank"><small>โอนไปยัง</small><b>${esc(item.bank_name||"—")}</b><strong>${esc(item.bank_account_number||"—")}</strong><span>${esc(item.bank_account_name||"—")}</span></div>`;return`<article class="wallet-admin-card"><header><div><span class="wallet-kind ${item.type}">${isDeposit?"เติมเครดิต":"ถอนเครดิต"}</span><b>${esc(item.id)}</b><small>${date(item.created_at)}</small></div><strong>${money.format(item.amount)}</strong></header><div class="wallet-admin-body">${detail}<div class="wallet-customer"><b>${customer}</b><span>${esc(item.phone||"ไม่มีเบอร์")}</span><small>${esc(item.user_id)}</small><span>เครดิตปัจจุบัน ${money.format(item.balance)}</span></div></div><footer><span class="wallet-status ${item.status}">${esc(walletStatusLabel[item.status]||item.status)}</span>${item.review_note?`<small>${esc(item.review_note)}</small>`:""}${item.status==="PENDING"?`<div class="row-actions"><button class="button" data-wallet-review="APPROVED" data-wallet-id="${item.id}">อนุมัติ</button><button class="button danger" data-wallet-review="REJECTED" data-wallet-id="${item.id}">ไม่อนุมัติ</button></div>`:""}</footer></article>`}
function showWalletProof(id){const item=state.walletRequests.find(row=>row.id===id);if(!item?.proof_image)return;modal(`สลิป ${item.id}`,`<img class="wallet-proof-full" src="${esc(item.proof_image)}" alt="สลิปชำระเงิน"><p class="notice">${esc(item.provider_message||"รอการตรวจสอบ")}</p>`)}
async function reviewWallet(id,next){const item=state.walletRequests.find(row=>row.id===id);if(!item)return;const action=next==="APPROVED"?"อนุมัติ":"ไม่อนุมัติ",warning=item.type==="WITHDRAWAL"&&next==="APPROVED"?"ยืนยันว่าโอนเงินให้ลูกค้าแล้วก่อนอนุมัติรายการนี้":"ตรวจสอบข้อมูลและยอดเงินให้ถูกต้อง";if(!confirm(`${action} ${item.type==="DEPOSIT"?"เติมเครดิต":"ถอนเครดิต"} ${money.format(item.amount)}?\n${warning}`))return;const note=prompt("หมายเหตุ (เว้นว่างได้)","")??null;if(note===null)return;try{await api(`/api/admin/wallet/requests/${encodeURIComponent(id)}`,{method:"POST",body:JSON.stringify({status:next,note})});toast(`${action}คำขอแล้ว`);await loadWalletRequests()}catch(error){toast(errorText(error))}}
async function releaseCommissions(){if(!confirm("จ่ายค่าคอมของออเดอร์ที่สำเร็จ เข้ากระเป๋าตัวแทนที่เชื่อม User ID แล้วตอนนี้?"))return;try{const result=await api("/api/admin/commissions/release",{method:"POST",body:"{}"});toast(`จ่ายค่าคอม ${result.paid} รายการ รวม ${money.format(result.total)}`);await Promise.all([loadWalletRequests(),loadAgents(),loadDashboard()])}catch(error){toast(errorText(error))}}
async function loadPromotions(){try{state.promotions=(await api("/api/admin/promotions")).promotions;$("#promotionCards").innerHTML=state.promotions.length?state.promotions.map(item=>`<article class="work-card promo-admin-card">${item.image?`<img src="${esc(item.image)}" alt="${esc(item.title)}">`:""}<span class="badge">${esc(item.discount_type)}</span><h3>${esc(item.title)}</h3><p>${esc(item.description||"")}</p><b>${item.discount_type==="PERCENT"?`${Number(item.discount_value)}%`:item.discount_type==="AMOUNT"?money.format(item.discount_value):"ประกาศ"}</b><p>สถานะ ${esc(item.status)}</p><footer><button class="button ghost" data-promotion-edit="${item.id}">แก้ไข</button>${state.user?.role==="OWNER"?`<button class="button danger" data-promotion-delete="${item.id}">ลบ</button>`:""}</footer></article>`).join(""):`<article class="work-card"><h3>ยังไม่มีโปรโมชั่น</h3></article>`}catch(error){toast(errorText(error))}}
function editPromotion(id){const item=state.promotions.find(row=>Number(row.id)===Number(id));if(!item)return;modal("แก้ไขโปรโมชั่น",`<form id="editPromotionForm" class="form"><input id="editPromoTitle" class="field" value="${esc(item.title)}" required><textarea id="editPromoDescription" class="field" placeholder="รายละเอียด">${esc(item.description||"")}</textarea><div class="three"><select id="editPromoType" class="field"><option value="INFO" ${item.discount_type==="INFO"?"selected":""}>ประกาศ</option><option value="PERCENT" ${item.discount_type==="PERCENT"?"selected":""}>ลดเปอร์เซ็นต์</option><option value="AMOUNT" ${item.discount_type==="AMOUNT"?"selected":""}>ลดเป็นบาท</option></select><input id="editPromoValue" class="field" type="number" min="0" value="${Number(item.discount_value||0)}"><select id="editPromoStatus" class="field"><option value="ACTIVE" ${item.status==="ACTIVE"?"selected":""}>เปิดใช้งาน</option><option value="INACTIVE" ${item.status!=="ACTIVE"?"selected":""}>ปิดไว้ก่อน</option></select></div>${item.image?`<label class="image-tile promo-edit-image"><img src="${esc(item.image)}" alt="รูปปัจจุบัน"><input id="keepPromoImage" type="checkbox" checked><span>เก็บรูปปัจจุบัน</span></label>`:""}<label class="upload-button" for="editPromoImage">＋ เปลี่ยนรูปโปรโมชั่น</label><input id="editPromoImage" type="file" accept="image/jpeg,image/png,image/webp" hidden><div id="editPromoPreview" class="image-preview"></div><button id="editPromoSubmit" class="button" type="submit">บันทึกโปรโมชั่น</button></form>`);$("#editPromoImage").onchange=event=>{const file=event.target.files[0];$("#editPromoPreview").innerHTML=file?`<div class="image-tile"><img src="${esc(URL.createObjectURL(file))}" alt="รูปใหม่"><span>รูปใหม่</span></div>`:""};$("#editPromotionForm").onsubmit=async event=>{event.preventDefault();const submit=$("#editPromoSubmit");try{submit.disabled=true;const file=$("#editPromoImage").files[0],image=file?await productImageData(file):$("#keepPromoImage")?.checked?item.image:"";await api(`/api/admin/promotions/${item.id}`,{method:"POST",body:JSON.stringify({title:$("#editPromoTitle").value,description:$("#editPromoDescription").value,discountType:$("#editPromoType").value,discountValue:$("#editPromoValue").value,status:$("#editPromoStatus").value,image})});toast("แก้ไขโปรโมชั่นแล้ว");closeModal();await loadPromotions()}catch(error){toast(errorText(error))}finally{submit.disabled=false}}}
async function deletePromotion(id){const item=state.promotions.find(row=>Number(row.id)===Number(id));if(!item||!confirm(`ลบโปรโมชั่น “${item.title}”?`))return;try{await api(`/api/admin/promotions/${id}`,{method:"DELETE"});toast("ลบโปรโมชั่นแล้ว");await loadPromotions()}catch(error){toast(errorText(error))}}

function thaiToday(){return new Date(Date.now()+7*3600000).toISOString().slice(0,10)}
function closingSelection(){const periodType=$("#closingType").value,periodKey=periodType==="MONTH"?$("#closingMonth").value:$("#closingDay").value;return{periodType,periodKey}}
function renderClosingPreview(preview,existing){state.closingPreview=preview;$("#cRevenue").textContent=money.format(preview.revenueTotal);$("#cCost").textContent=money.format(preview.actualCost);$("#cProfit").textContent=money.format(preview.grossProfit);$("#cNet").textContent=money.format(preview.netProfit);$("#cCommission").textContent=`ค่าคอม ${money.format(preview.commissionTotal)}`;$("#cTransfer").textContent=money.format(preview.transferTotal);$("#cCash").textContent=money.format(preview.cashTotal);$("#cCod").textContent=money.format(preview.codTotal);$("#cWalletDeposit").textContent=money.format(preview.walletDepositTotal);$("#cWalletWithdrawal").textContent=money.format(preview.walletWithdrawalTotal);$("#cPending").textContent=`${preview.pendingOrderCount} · ${money.format(preview.pendingOrderTotal)}`;$("#closingPeriodLabel").textContent=`${preview.periodType==="DAY"?"วันที่":"เดือน"} ${preview.periodKey} · ${preview.orderCount} ออเดอร์`;const notice=$("#closingExistingNotice"),button=$("#closingCreate");notice.classList.toggle("hidden",!existing);notice.innerHTML=existing?`✓ ปิดยอดรอบนี้แล้วเมื่อ <b>${date(existing.closed_at)}</b> โดย ${esc(existing.closed_by_name)} · เปิดดูรายละเอียดได้จากประวัติด้านล่าง`:"";button.disabled=Boolean(existing);button.textContent=existing?"ปิดยอดแล้ว":"ยืนยันปิดยอด"}
function closingCard(item){const difference=item.cashDifference===null?"ไม่ได้บันทึก":money.format(item.cashDifference),differenceClass=item.cashDifference===null?"":Math.abs(item.cashDifference)<.01?"match":item.cashDifference>0?"plus":"minus";return`<article class="closing-card"><div><span class="closing-kind">${item.period_type==="DAY"?"รายวัน":"รายเดือน"}</span><h3>${esc(item.period_key)}</h3><small>ปิดโดย ${esc(item.closed_by_name)} · ${date(item.closed_at)}</small></div><div><span>รายรับ</span><b>${money.format(item.revenueTotal)}</b><small>${item.orderCount} ออเดอร์</small></div><div><span>กำไรหลังค่าคอม</span><b>${money.format(item.netProfit)}</b><small>ต้นทุน ${money.format(item.actualCost)}</small></div><div class="cash-difference ${differenceClass}"><span>เงินสดต่าง</span><b>${difference}</b></div><button class="button ghost small" data-closing-detail="${esc(item.id)}">ดู / พิมพ์</button></article>`}
async function loadClosings(){try{const today=thaiToday();if(!$("#closingDay").value)$("#closingDay").value=today;if(!$("#closingMonth").value)$("#closingMonth").value=today.slice(0,7);const selection=closingSelection(),result=await api(`/api/admin/closings?${new URLSearchParams(selection)}`);state.closings=result.closings;renderClosingPreview(result.preview,result.existing);$("#closingRows").innerHTML=state.closings.length?state.closings.map(closingCard).join(""):'<p class="muted">ยังไม่มีประวัติปิดยอดประเภทนี้</p>'}catch(error){toast(errorText(error))}}
async function createFinancialClosing(){const selection=closingSelection(),preview=state.closingPreview;if(!preview||!confirm(`ยืนยันปิดยอด${selection.periodType==="DAY"?"รายวัน":"รายเดือน"} ${selection.periodKey}?\n\nรายรับ ${money.format(preview.revenueTotal)} · กำไรหลังค่าคอม ${money.format(preview.netProfit)}\nข้อมูลจะถูกบันทึกเป็น Snapshot และปิดซ้ำไม่ได้`))return;try{await api("/api/admin/closings",{method:"POST",body:JSON.stringify({...selection,actualCash:$("#closingActualCash").value,note:$("#closingNote").value})});toast("ปิดยอดและบันทึก Snapshot แล้ว");$("#closingNote").value="";await loadClosings()}catch(error){toast(errorText(error))}}
function showClosingDetail(id){const item=state.closings.find(row=>row.id===id);if(!item)return;modal(`ใบปิดยอด ${item.period_key}`,`<section class="closing-detail"><header><img src="/assets/jigz-agent-logo.png" alt="JIGᶻ AGENT"><div><h2>รายงานปิดยอด${item.period_type==="DAY"?"รายวัน":"รายเดือน"}</h2><p>${esc(item.period_key)} · ${esc(item.id)}</p></div></header><div class="closing-detail-grid"><p><span>รายรับสุทธิ</span><b>${money.format(item.revenueTotal)}</b></p><p><span>ยอดขายก่อนส่วนลด</span><b>${money.format(item.grossSales)}</b></p><p><span>ส่วนลด</span><b>${money.format(item.discountTotal)}</b></p><p><span>ค่าจัดส่ง</span><b>${money.format(item.shippingTotal)}</b></p><p><span>โอน / เงินสด / COD</span><b>${money.format(item.transferTotal)} / ${money.format(item.cashTotal)} / ${money.format(item.codTotal)}</b></p><p><span>ต้นทุนจริง FIFO</span><b>${money.format(item.actualCost)}</b></p><p><span>กำไรขั้นต้น</span><b>${money.format(item.grossProfit)}</b></p><p><span>ค่าคอมจ่ายแล้ว</span><b>${money.format(item.commissionTotal)}</b></p><p><span>กำไรหลังค่าคอม</span><b>${money.format(item.netProfit)}</b></p><p><span>เงินสดนับจริง / ส่วนต่าง</span><b>${item.actualCash===null?"—":money.format(item.actualCash)} / ${item.cashDifference===null?"—":money.format(item.cashDifference)}</b></p><p><span>เติม / ถอนเครดิต</span><b>${money.format(item.walletDepositTotal)} / ${money.format(item.walletWithdrawalTotal)}</b></p><p><span>ออเดอร์ค้าง</span><b>${item.pendingOrderCount} · ${money.format(item.pendingOrderTotal)}</b></p></div><p class="notice"><b>หมายเหตุ</b><br>${esc(item.note||"—")}</p><footer><span>ปิดโดย ${esc(item.closed_by_name)}<br>${date(item.closed_at)}</span><button class="button" onclick="window.print()">พิมพ์ / บันทึก PDF</button></footer></section>`)}

async function loadReports(){try{const from=$("#reportFrom"),to=$("#reportTo"),agentSelect=$("#reportAgent");if(from&&!from.value)from.value=new Date(Date.now()-29*86400000).toISOString().slice(0,10);if(to&&!to.value)to.value=new Date().toISOString().slice(0,10);if(agentSelect&&agentSelect.options.length===1){if(!state.agents.length)state.agents=(await api("/api/admin/agents")).agents;agentSelect.innerHTML='<option value="">ทุกตัวแทน</option>'+state.agents.map(agent=>`<option value="${esc(agent.code)}">${esc(agent.code)} · ${esc(agent.name)}</option>`).join("")}const query=new URLSearchParams();if(from?.value)query.set("from",from.value);if(to?.value)query.set("to",to.value);if($("#reportStatus")?.value)query.set("status",$("#reportStatus").value);if(agentSelect?.value)query.set("agent",agentSelect.value);state.reports=await api(`/api/admin/reports?${query}`);const report=state.reports;$("#fRevenue").textContent=money.format(report.totals.revenue);$("#fCost").textContent=money.format(report.totals.cost);$("#fProfit").textContent=money.format(report.totals.profit);$("#fOrders").textContent=report.totals.orders;$("#financeStatuses").innerHTML=report.statuses.map(item=>`<div class="summary-row"><b>${esc(labels[item.status]||item.status)}</b><span>${item.total} ออเดอร์</span><b>${money.format(item.amount)}</b></div>`).join("")||'<p class="muted">ไม่พบข้อมูลตามตัวกรอง</p>';const max=Math.max(1,...report.days.map(item=>Number(item.revenue)));$("#salesBars").innerHTML=report.days.length?report.days.map(item=>`<i class="bar" style="--h:${Math.max(4,Number(item.revenue)/max*100)}%" data-tip="${esc(item.day)} · ${money.format(item.revenue)}"></i>`).join(""):'<p>ยังไม่มีข้อมูล</p>';$("#topProducts").innerHTML=report.topProducts.length?report.topProducts.map((item,index)=>`<div class="summary-row"><b>${index+1}. ${esc(item.product_name)}</b><span>${Number(item.quantity)} หน่วย</span><b>${money.format(item.revenue)}</b></div>`).join(""):'<p class="muted">ไม่พบสินค้าตามตัวกรอง</p>';$("#auditRows").innerHTML=report.audit.map(item=>`<tr><td>${date(item.created_at)}</td><td>${esc(item.action)}</td><td>${esc(item.entity_type)}</td><td>${esc(item.entity_id||"—")}</td><td>${esc(item.actor_id||"SYSTEM")}</td></tr>`).join("");if($("#reportFilterSummary"))$("#reportFilterSummary").textContent=`ข้อมูล ${report.filters.dateFrom} ถึง ${report.filters.dateTo}${report.filters.status?` · ${labels[report.filters.status]||report.filters.status}`:""}${report.filters.agentCode?` · ตัวแทน ${report.filters.agentCode}`:""} · ${report.totals.orders} ออเดอร์`}catch(error){toast(errorText(error))}}
async function loadSettings(){try{const values=(await api("/api/admin/settings")).settings;$("#setShopName").value=values.shop_name||"";$("#setAnnouncement").value=values.announcement||"";$("#setShopOpen").value=values.shop_open||"true";$("#setShipping").value=values.shipping_fee||"0";$("#setPointsRate").value=values.points_rate||"100";$("#setTheme").value=values.theme||"space";$("#setLine").value=values.line_oa||"";$("#setInstagram").value=values.instagram||"";$("#setBankName").value=values.bank_name||"";$("#setBankAccount").value=values.bank_account||"";$("#setBankNumber").value=values.bank_number||"";$("#setQrUrl").value=values.qr_image?.startsWith("http")?values.qr_image:"";$("#settingsForm").dataset.qr=values.qr_image||"";state.sound={enabled:values.notification_sound_enabled!=="false",volume:Math.min(1,Math.max(0,Number(values.notification_volume??1))),data:values.notification_sound||"",name:values.notification_sound_name||"เสียงมาตรฐาน JIGᶻ"};$("#settingsForm").dataset.sound=state.sound.data;$("#settingsForm").dataset.soundName=state.sound.name;$("#setSoundEnabled").value=String(state.sound.enabled);$("#setSoundVolume").value=String(state.sound.volume);$("#setVolumeValue").textContent=`${Math.round(state.sound.volume*100)}%`;$("#setSoundName").textContent=state.sound.name}catch(error){toast(errorText(error))}}

async function loadChat(){try{const messages=(await api(`/api/admin/chat?after=${state.lastChatId}`)).messages;if(messages.length){state.lastChatId=messages.at(-1).id;const root=$("#chatMessages");root.insertAdjacentHTML("beforeend",messages.map(message=>`<div class="message ${message.user_id===state.user?.id?"me":""}"><small>${esc(message.display_name)} · ${date(message.created_at)}</small>${esc(message.message)}</div>`).join(""));root.scrollTop=root.scrollHeight}if(!state.chatTimer)state.chatTimer=setInterval(()=>{if($("#chat").classList.contains("active"))loadChat()},4000)}catch(error){toast(errorText(error))}}

function urlB64(value){const padding="=".repeat((4-value.length%4)%4),raw=atob((value+padding).replace(/-/g,"+").replace(/_/g,"/"));return Uint8Array.from(raw,char=>char.charCodeAt(0))}
function audioData(file){return new Promise((resolve,reject)=>{const allowed=["audio/mpeg","audio/wav","audio/x-wav","audio/ogg","audio/mp4","audio/x-m4a"];if(!file||!allowed.includes(file.type))return reject(new Error("invalid_audio"));if(file.size>921600)return reject(new Error("audio_too_large"));const reader=new FileReader();reader.onerror=()=>reject(new Error("invalid_audio"));reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file)})}
function ensureAudioContext(){const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)return null;state.audioContext??=new AudioContextClass();if(state.audioContext.state==="suspended")state.audioContext.resume().catch(()=>{});return state.audioContext}
async function playAlertSound(force=false){if(!force&&!state.sound.enabled)return false;const volume=Math.min(1,Math.max(0,Number(state.sound.volume)));try{if(state.sound.data){state.currentAlertAudio?.pause();const audio=new Audio(state.sound.data);audio.volume=volume;state.currentAlertAudio=audio;await audio.play();return true}const context=ensureAudioContext();if(!context)return false;const now=context.currentTime,frequencies=[880,1320,1760,1320];frequencies.forEach((frequency,index)=>{const oscillator=context.createOscillator(),gain=context.createGain(),start=now+index*.16;oscillator.type=index%2?"sine":"triangle";oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(Math.max(.001,volume*.32),start+.025);gain.gain.exponentialRampToValueAtTime(.0001,start+.14);oscillator.connect(gain).connect(context.destination);oscillator.start(start);oscillator.stop(start+.15)});return true}catch{return false}}
async function monitorNewOrders(){try{const orders=(await api("/api/admin/orders")).orders,ids=new Set(orders.map(order=>order.id));if(state.knownNewOrders){const fresh=orders.filter(order=>!state.knownNewOrders.has(order.id));if(fresh.length){await playAlertSound();toast(`🔔 มีออเดอร์ใหม่ ${fresh.length} รายการ`);if($("#dashboard").classList.contains("active"))loadDashboard()}}state.knownNewOrders=ids}catch{}}
function startOrderMonitor(){if(state.orderMonitorTimer)return;monitorNewOrders();state.orderMonitorTimer=setInterval(monitorNewOrders,8000)}
async function checkPush(){if(!("serviceWorker"in navigator)||!("PushManager"in window)||!("Notification"in window)){$("#pushEnable").disabled=true;$("#pushEnable").textContent="🔕 ไม่รองรับ";return}try{const registration=await navigator.serviceWorker.register("/sw.js",{scope:"/"}),subscription=await registration.pushManager.getSubscription();if(subscription&&Notification.permission==="granted"){$("#pushEnable").textContent="🔔 เปิดอยู่";$("#pushTest").classList.remove("hidden")}}catch{}}
async function enablePush(){try{const permission=await Notification.requestPermission();if(permission!=="granted")throw new Error("permission_denied");const registration=await navigator.serviceWorker.register("/sw.js",{scope:"/"}),config=await api("/api/admin/push/config"),existing=await registration.pushManager.getSubscription(),subscription=existing||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlB64(config.publicKey)});await api("/api/admin/push/subscribe",{method:"POST",body:JSON.stringify({subscription:subscription.toJSON()})});$("#pushEnable").textContent="🔔 เปิดอยู่";$("#pushTest").classList.remove("hidden");toast("เปิดการแจ้งเตือนแล้ว")}catch(error){toast(error.message==="permission_denied"?"อุปกรณ์ปฏิเสธการแจ้งเตือน":errorText(error))}}
async function imageData(file,maxWidth=1000,quality=.72,format="image/jpeg"){return new Promise((resolve,reject)=>{const image=new Image(),reader=new FileReader();reader.onerror=reject;reader.onload=()=>{image.onload=()=>{const scale=Math.min(1,maxWidth/image.width),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext("2d").drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL(format,quality))};image.onerror=()=>reject(new Error("invalid_image"));image.src=reader.result};reader.readAsDataURL(file)})}

document.addEventListener("click",event=>{const target=event.target.closest("button,a");if(!target)return;if(target.dataset.view)showView(target.dataset.view);if(target.dataset.viewJump)showView(target.dataset.viewJump);if(target.dataset.orderDetail)orderDetail(target.dataset.orderDetail);if(target.dataset.orderAction){const id=target.dataset.orderId,next=target.dataset.orderAction;next==="SHIP"?shippingModal(id):next==="COD_RECEIVED"?confirmCod(id):transition(id,next)}if(target.dataset.posAdd)addPos(target.dataset.posAdd);if(target.dataset.posQty){const line=state.posCart.find(item=>item.key===target.dataset.posKey);if(line){line.qty+=Number(target.dataset.posQty);if(line.qty<=0)state.posCart=state.posCart.filter(item=>item!==line);renderPosCart()}}if(target.dataset.productCost)focusProductCost(target.dataset.productCost);if(target.dataset.productEdit)editProduct(target.dataset.productEdit);if(target.dataset.productDelete)deleteProduct(target.dataset.productDelete);if(target.dataset.agentEdit)editAgent(target.dataset.agentEdit);if(target.dataset.agentDelete)deleteAgent(target.dataset.agentDelete);if(target.dataset.commissionEdit)editCommission(target.dataset.commissionEdit);if(target.dataset.commissionDelete)deleteCommission(target.dataset.commissionDelete);if(target.dataset.walletProof)showWalletProof(target.dataset.walletProof);if(target.dataset.walletReview)reviewWallet(target.dataset.walletId,target.dataset.walletReview);if(target.dataset.pointsUser)pointsModal(target.dataset.pointsUser);if(target.dataset.staffRole)changeStaffRole(target.dataset.staffId,target.dataset.staffRole);if(target.dataset.userDelete)deleteUser(target.dataset.userDelete,target.dataset.userSource);if(target.dataset.ownerReview)reviewOwnerDeletion(target.dataset.ownerRequest,target.dataset.ownerReview);if(target.dataset.closingDetail)showClosingDetail(target.dataset.closingDetail);if(target.dataset.action==="refresh-dashboard")loadDashboard();if(target.dataset.action==="load-orders")loadOrders();if(target.dataset.action==="load-payments")loadOrders();if(target.dataset.action==="load-shipping")loadOrders();if(target.dataset.action==="load-products")loadProducts();if(target.dataset.action==="load-users")loadUsers();if(target.dataset.action==="load-staff")loadStaff();if(target.dataset.action==="load-agents")loadAgents();if(target.dataset.action==="load-promotions")loadPromotions();if(target.dataset.action==="load-wallet")loadWalletRequests();if(target.dataset.action==="release-commissions")releaseCommissions();if(target.dataset.action==="load-closings")loadClosings();if(target.dataset.action==="load-reports")loadReports();if(target.dataset.action==="clear-pos"){state.posCart=[];renderPosCart()}});
